package com.citacloud.app.services;
import com.citacloud.app.models.*; import com.citacloud.app.repositories.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*;
@Service public class FacturacionService {private final FacturaRepository facturas;private final PagoRepository pagos;private final PacienteRepository pacientes;private final CargoFinancieroRepository cargos;private final AuditoriaService auditoria;public FacturacionService(FacturaRepository f,PagoRepository p,PacienteRepository pa,CargoFinancieroRepository c,AuditoriaService a){facturas=f;pagos=p;pacientes=pa;cargos=c;auditoria=a;}public List<Factura> listar(UUID e){return facturas.findByEmpresaIdOrderByFechaDesc(e);}public List<Pago> listarPagos(UUID e){return pagos.findByEmpresaIdOrderByFechaDesc(e);}@Transactional public Factura crear(UUID e,UUID pacienteId,String numero,BigDecimal subtotal,BigDecimal descuento,BigDecimal impuestos){Paciente paciente=pacientes.findByIdAndEmpresaId(pacienteId,e).orElseThrow(()->new IllegalArgumentException("Paciente no encontrado para esta empresa."));if(numero==null||numero.isBlank())throw new IllegalArgumentException("El número de factura es obligatorio.");Factura f=new Factura();f.setEmpresaId(e);f.setPaciente(paciente);f.setNumero(numero.trim());f.setFecha(LocalDate.now());f.setSubtotal(n(subtotal));f.setDescuento(n(descuento));f.setImpuestos(n(impuestos));BigDecimal total=n(subtotal).subtract(n(descuento)).add(n(impuestos));if(total.signum()<0)throw new IllegalArgumentException("El total no puede ser negativo.");f.setTotal(total);f.setSaldo(total);f.setEstado("EMITIDA");f=facturas.save(f);CargoFinanciero c=new CargoFinanciero();c.setEmpresaId(e);c.setPaciente(paciente);c.setFactura(f);c.setOrigen("FACTURA");c.setReferenciaOrigen(f.getNumero());c.setConcepto("Factura "+f.getNumero());c.setFecha(f.getFecha());c.setMontoOriginal(total);c.setMontoPagado(BigDecimal.ZERO);c.setSaldo(total);c.setEstado("PENDIENTE");cargos.save(c);auditoria.registrar(e,null,"FACTURACION","CREAR","FACTURA",f.getId(),f.getNumero());return f;}@Transactional public Pago registrarPago(UUID e,UUID facturaId,BigDecimal monto,String metodo,String referencia){Factura f=facturas.findByIdAndEmpresaId(facturaId,e).orElseThrow(()->new IllegalArgumentException("Factura no encontrada para esta empresa."));if("ANULADA".equals(f.getEstado()))throw new IllegalArgumentException("No se puede pagar una factura anulada.");monto=n(monto);if(monto.signum()<=0||monto.compareTo(f.getSaldo())>0)throw new IllegalArgumentException("El monto debe ser mayor que cero y no superar el saldo.");Pago p=new Pago();p.setEmpresaId(e);p.setFactura(f);p.setPaciente(f.getPaciente());p.setFecha(LocalDate.now());p.setMonto(monto);p.setMetodoPago(metodo);p.setReferencia(referencia);p=pagos.save(p);f.setMontoPagado(n(f.getMontoPagado()).add(monto));f.setSaldo(f.getTotal().subtract(f.getMontoPagado()));f.setEstado(f.getSaldo().signum()==0?"PAGADA":"PARCIAL");facturas.save(f);auditoria.registrar(e,null,"PAGOS","REGISTRAR_PAGO","PAGO",p.getId(),monto.toPlainString());return p;}private BigDecimal n(BigDecimal n){return n==null?BigDecimal.ZERO:n;}}
